{"file_path":"./src/csv.js","content":"/**
 * RFC 4180 style CSV reader and writer with a configurable delimiter and quote
 * character, byte-order-mark handling and exact positions on failure.
 */

/** Failure raised by the CSV reader and writer. */
export class CsvError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [line] 1-based line the failure was found on
   * @param {number} [column] 1-based column, counted in UTF-16 code units
   */
  constructor(message, line, column) {
    super(message);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function isLineTerminatorChar(ch) {
  return ch === '\r' || ch === '\n';
}

function resolveDialect(options) {
  const delimiter = options.delimiter ?? ',';
  const quote = options.quote ?? '"';
  if (delimiter.length !== 1) throw new CsvError('delimiter must be a single character');
  if (quote.length !== 1) throw new CsvError('quote must be a single character');
  if (delimiter === quote) throw new CsvError('delimiter and quote must differ');
  if (isLineTerminatorChar(delimiter) || isLineTerminatorChar(quote)) {
    throw new CsvError('delimiter and quote must not be line terminators');
  }
  return { delimiter, quote };
}

/**
 * Read a CSV document into records.
 *
 * @param {string} text document source
 * @param {{ delimiter?: string, quote?: string, strictWidth?: boolean }} [options] dialect and width policy
 * @returns {string[][]} one array of field values per record
 */
export function parse(text, options = {}) {
  if (typeof text !== 'string') throw new CsvError('input must be a string');
  const { delimiter, quote } = resolveDialect(options);
  const strictWidth = !!options.strictWidth;

  let i = 0;
  const n = text.length;
  if (n > 0 && text[0] === '﻿') i = 1;
  if (i >= n) return [];

  const records = [];
  let line = 1;
  let lineStart = i;
  let currentRecord = [];
  let recordStartLine = line;
  let fieldWidth = null;

  for (;;) {
    let value;
    if (i < n && text[i] === quote) {
      const openLine = line;
      const openCol = i - lineStart + 1;
      i += 1;
      let content = '';
      let closed = false;
      while (i < n) {
        const ch = text[i];
        if (ch === quote) {
          if (i + 1 < n && text[i + 1] === quote) {
            content += quote;
            i += 2;
            continue;
          }
          i += 1;
          closed = true;
          break;
        }
        if (ch === '\r') {
          if (i + 1 < n && text[i + 1] === '\n') {
            content += '\r\n';
            i += 2;
          } else {
            content += '\r';
            i += 1;
          }
          line += 1;
          lineStart = i;
          continue;
        }
        if (ch === '\n') {
          content += '\n';
          i += 1;
          line += 1;
          lineStart = i;
          continue;
        }
        content += ch;
        i += 1;
      }
      if (!closed) throw new CsvError('unterminated quoted field', openLine, openCol);
      value = content;
      if (i < n) {
        const ch = text[i];
        if (ch !== delimiter && ch !== '\r' && ch !== '\n') {
          throw new CsvError(`unexpected character after closing quote: ${ch}`, line, i - lineStart + 1);
        }
      }
    } else {
      const start = i;
      while (i < n && text[i] !== delimiter && text[i] !== '\r' && text[i] !== '\n') i += 1;
      value = text.slice(start, i);
    }

    currentRecord.push(value);

    if (i < n && text[i] === delimiter) {
      i += 1;
      continue;
    }

    if (i < n) {
      if (text[i] === '\r') {
        if (i + 1 < n && text[i + 1] === '\n') i += 2;
        else i += 1;
        line += 1;
        lineStart = i;
      } else if (text[i] === '\n') {
        i += 1;
        line += 1;
        lineStart = i;
      }
    }

    if (fieldWidth === null) {
      fieldWidth = currentRecord.length;
    } else if (strictWidth && currentRecord.length !== fieldWidth) {
      throw new CsvError(`expected ${fieldWidth} fields, got ${currentRecord.length}`, recordStartLine);
    }
    records.push(currentRecord);

    if (i >= n) break;

    currentRecord = [];
    recordStartLine = line;
  }

  return records;
}

/**
 * Serialise one field, quoting it when the dialect requires it.
 *
 * @param {unknown} value field value
 * @param {{ delimiter?: string, quote?: string, alwaysQuote?: boolean }} [options] dialect and quoting policy
 * @returns {string} the field as it appears in the document
 */
export function escapeField(value, options = {}) {
  const delimiter = options.delimiter ?? ',';
  const quote = options.quote ?? '"';

  let text;
  if (typeof value === 'string') {
    text = value;
  } else if (value === null || value === undefined) {
    text = '';
  } else if (typeof value === 'boolean') {
    text = String(value);
  } else if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new CsvError(`unsupported field value: ${value}`);
    text = String(value);
  } else {
    throw new CsvError(`unsupported field type: ${typeof value}`);
  }

  const needsQuote =
    !!options.alwaysQuote ||
    text.includes(delimiter) ||
    text.includes(quote) ||
    text.includes('\r') ||
    text.includes('\n') ||
    text.includes('﻿');

  if (!needsQuote) return text;
  return quote + text.split(quote).join(quote + quote) + quote;
}

/**
 * Write records as a CSV document.
 *
 * @param {unknown[][]} rows records to write
 * @param {{ delimiter?: string, quote?: string, newline?: string, bom?: boolean, alwaysQuote?: boolean }} [options]
 *   dialect, terminator and byte-order-mark policy
 * @returns {string} the document, with a terminator after every record
 */
export function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) throw new CsvError('rows must be an array');
  const delimiter = options.delimiter ?? ',';
  const quote = options.quote ?? '"';
  const newline = options.newline ?? '\r\n';
  if (newline !== '\r\n' && newline !== '\n' && newline !== '\r') {
    throw new CsvError('newline must be a line terminator');
  }

  let out = options.bom ? '﻿' : '';
  for (let r = 0; r < rows.length; r += 1) {
    const record = rows[r];
    if (!Array.isArray(record)) throw new CsvError(`record ${r} is not an array`);
    if (record.length === 0) throw new CsvError(`record ${r} has no fields`);
    const fields = record.map((field) => escapeField(field, { delimiter, quote, alwaysQuote: options.alwaysQuote }));
    out += fields.join(delimiter) + newline;
  }
  return out;
}
"}

