const TYPE_RANK = { number: 0, string: 1, boolean: 2 };

/**
 * Tests whether a value counts as absent for sorting purposes.
 * @param {unknown} value Value to classify.
 * @returns {boolean} True for null, undefined, and NaN.
 */
function isAbsent(value) {
  return value === null || value === undefined || (typeof value === 'number' && Number.isNaN(value));
}

/**
 * Compares two present (non-absent) values of the same or different
 * supported types.
 * @param {number|string|boolean} a First value.
 * @param {number|string|boolean} b Second value.
 * @returns {number} Negative, zero, or positive.
 */
function comparePresent(a, b) {
  const ta = typeof a;
  const tb = typeof b;
  if (ta !== 'number' && ta !== 'string' && ta !== 'boolean') {
    throw new TypeError(`unsupported value type: ${ta}`);
  }
  if (tb !== 'number' && tb !== 'string' && tb !== 'boolean') {
    throw new TypeError(`unsupported value type: ${tb}`);
  }
  if (ta !== tb) return TYPE_RANK[ta] - TYPE_RANK[tb];
  if (ta === 'number') {
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
  }
  if (ta === 'boolean') {
    return (a ? 1 : 0) - (b ? 1 : 0);
  }
  // strings: compare by Unicode code point
  const left = Array.from(a, (c) => c.codePointAt(0));
  const right = Array.from(b, (c) => c.codePointAt(0));
  const len = Math.min(left.length, right.length);
  for (let i = 0; i < len; i += 1) {
    if (left[i] !== right[i]) return left[i] - right[i];
  }
  return left.length - right.length;
}

/**
 * Total order over sortable values: absent values first, then numbers,
 * strings, and booleans.
 * @param {unknown} a First value.
 * @param {unknown} b Second value.
 * @returns {number} Negative, zero, or positive.
 */
export function compareValues(a, b) {
  const aAbsent = isAbsent(a);
  const bAbsent = isAbsent(b);
  if (aAbsent && bAbsent) return 0;
  if (aAbsent) return -1;
  if (bAbsent) return 1;
  return comparePresent(a, b);
}

/**
 * Reads a value out of a row using a string dot-path or a function.
 * @param {unknown} row Row to read from.
 * @param {string|Function} key Property path or accessor function.
 * @returns {unknown} The read value, or undefined if a path step is missing.
 */
function readKey(row, key) {
  if (typeof key === 'function') return key(row);
  const parts = key.split('.');
