{"file_path":"src/glob.js","content":"/**
 * Glob patterns compiled to path matchers: wildcards that stop at `/`,
 * whole-segment globstars, POSIX-style character classes, backslash escapes and
 * the leading-dot rule.
 */

/** Failure raised while compiling a pattern. */
export class GlobError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [index] 0-based index into the pattern where the fault starts
   */
  constructor(message, index) {
    super(message);
    this.name = 'GlobError';
    this.index = index;
  }
}

const LITERAL_ESCAPE_RE = /[.*+?^${}()|[\]\\/]/g;

function escapeLiteral(char) {
  return char.replace(LITERAL_ESCAPE_RE, '\\$&');
}

function escapeClassChar(char, fromEscape) {
  if (char === ']') return '\\]';
  if (char === '\\') return '\\\\';
  if (char === '-' && fromEscape) return '\\-';
  return char;
}

/**
 * Parse a pattern into per-segment regex fragments, validating syntax along
 * the way and throwing `GlobError` with the correct absolute index on failure.
 */
function parsePattern(pattern, dot) {
  const n = pattern.length;
  let i = 0;

  const segments = [];
  let curRaw = '';
  let curParts = [];
  let curIsFirstToken = true;

  function addToken(fragment, isLiteralDot) {
    let frag = fragment;
    if (curIsFirstToken && !dot && !isLiteralDot) {
      frag = `(?!\\.)${frag}`;
    }
    curParts.push(frag);
    curIsFirstToken = false;
  }

  function flushSegment() {
    if (curRaw === '**') {
      segments.push({ globstar: true });
    } else {
      segments.push({ globstar: false, source: curParts.join('') });
    }
    curRaw = '';
    curParts = [];
    curIsFirstToken = true;
  }

  while (i < n) {
    const c = pattern[i];

    if (c === '\\') {
      if (i + 1 >= n) throw new GlobError('trailing backslash', i);
      const esc = pattern[i + 1];
      curRaw += c + esc;
      addToken(escapeLiteral(esc), esc === '.');
      i += 2;
      continue;
    }

    if (c === '/') {
      flushSegment();
      i += 1;
      continue;
    }

    if (c === '*') {
      let k = i;
      while (pattern[k] === '*') k += 1;
      curRaw += pattern.slice(i, k);
      addToken('[^/]*', false);
      i = k;
      continue;
    }

    if (c === '?') {
      curRaw += c;
      addToken('[^/]', false);
      i += 1;
      continue;
    }

    if (c === '[') {
      const classStart = i;
      let k = i + 1;
      let negate = false;
      if (pattern[k] === '!' || pattern[k] === '^') {
        negate = true;
        k += 1;
      }
      let bodyChars = '';
      let firstInClass = true;
      while (true) {
        if (k >= n) throw new GlobError('unterminated character class', classStart);
        const cc = pattern[k];
        if (cc === '\\') {
          if (k + 1 >= n) throw new GlobError('trailing backslash', k);
          const esc = pattern[k + 1];
          bodyChars += escapeClassChar(esc, true);
          k += 2;
          firstInClass = false;
          continue;
        }
        if (cc === ']' && !firstInClass) {
          k += 1;
          break;
        }
        if (cc === '/') throw new GlobError('path separator in character class', k);
        bodyChars += escapeClassChar(cc, false);
        k += 1;
        firstInClass = false;
        continue;
      }
      const classSource = negate ? `[^/${bodyChars}]` : `[${bodyChars}]`;
      curRaw += pattern.slice(classStart, k);
      addToken(classSource, false);
      i = k;
      continue;
    }

    curRaw += c;
    addToken(escapeLiteral(c), c === '.');
    i += 1;
  }

  flushSegment();
  return segments;
}

function collapseGlobstars(segments) {
  const out = [];
  for (const seg of segments) {
    if (seg.globstar && out.length > 0 && out[out.length - 1].globstar) continue;
    out.push(seg);
  }
  return out;
}

function buildFullSource(segments, dot) {
