{"file_path":"src/sortBy.js","content":"/**
 * Stable multi-key sorting with per-key direction and null placement.
 */

const TYPE_RANK = { number: 0, string: 1, boolean: 2 };

/**
 * Determines whether a value counts as absent: null, undefined, or NaN.
 * @param {unknown} value Value to classify.
 * @returns {boolean} True when the value is absent.
 */
function isAbsent(value) {
  return value === null || value === undefined || (typeof value === 'number' && Number.isNaN(value));
}

/**
 * Classifies a present value's type, raising on unsupported types.
 * @param {unknown} value Value to classify.
 * @returns {'number'|'string'|'boolean'} The value's supported type.
 */
function classifyType(value) {
  const t = typeof value;
  if (t === 'number' || t === 'string' || t === 'boolean') return t;
  throw new TypeError(`unsupported value type: ${t}`);
}

/**
 * Compares two strings by Unicode code point, not UTF-16 code unit.
 * @param {string} a First string.
 * @param {string} b Second string.
 * @returns {number} Negative, zero, or positive.
 */
function compareStrings(a, b) {
  const left = [...a];
  const right = [...b];
  const len = Math.min(left.length, right.length);
  for (let i = 0; i < len; i += 1) {
    const lc = left[i].codePointAt(0);
    const rc = right[i].codePointAt(0);
    if (lc !== rc) return lc - rc;
  }
  return left.length - right.length;
}

/**
 * Total order over sortable values: absent values first, then numbers,
 * strings, and booleans.
 * @param {unknown} a First value.
 * @param {unknown} b Second value.
 * @returns {number} Negative, zero, or positive.
 */
export function compareValues(a, b) {
  const aAbsent = isAbsent(a);
  const bAbsent = isAbsent(b);
  if (aAbsent && bAbsent) return 0;
  if (aAbsent) {
    // still validate b's type if present, per spec ordering of checks
    classifyType(b);
    return -1;
  }
  if (bAbsent) {
    classifyType(a);
    return 1;
  }
  const ta = classifyType(a);
  const tb = classifyType(b);
  if (ta !== tb) return TYPE_RANK[ta] - TYPE_RANK[tb];
  if (ta === 'number') {
    const na = a === 0 ? 0 : a;
    const nb = b === 0 ? 0 : b;
    return na === nb ? 0 : na < nb ? -1 : 1;
  }
  if (ta === 'string') return compareStrings(a, b);
  // boolean
  return (a ? 1 : 0) - (b ? 1 : 0);
}

/**
 * Reads a value out of a row by a string dot-path or a reader function.
 * @param {unknown} row Row to read from.
 * @param {string|Function} key Property path or reader function.
 * @returns {unknown} The extracted value, or undefined when the path is missing.
 */
function readKey(row, key) {
  if (typeof key === 'function') return key(row);
  return key.split('.').reduce((value, part) => (value === null || value === undefined ? undefined : value[part]), row);
}

/**
 * Validates and normalizes one key spec.
 * @param {unknown} spec Key spec to validate.
 * @returns {{ read: Function, direction: 'asc'|'desc', nulls: 'first'|'last' }} Normalized spec.
 */
function normalizeSpec(spec) {
  if (typeof spec !== 'object' || spec === null || Array.isArray(spec)) {
    throw new TypeError('key spec must be an object');
  }
  const { key, direction = 'asc', nulls = 'last' } = spec;
  if (typeof key !== 'string' && typeof key !== 'function') {
    throw new TypeError('key must be a string path or a function');
  }
  if (direction !== 'asc' && direction !== 'desc') {
    throw new RangeError(`unknown direction: ${JSON.stringify(direction)}`);
  }
  if (nulls !== 'first' && nulls !== 'last') {
    throw new RangeError(`unknown null placement: ${JSON.stringify(nulls)}`);
  }
  return {
    read: (row) => readKey(row, key),
    direction,
    nulls,
  };
}

/**
 * Validates and normalizes the full spec list.
 * @param {unknown} specs Key specs to validate.
 * @returns {{ read: Function, direction: 'asc'|'desc', nulls: 'first'|'last' }[]} Normalized specs.
 */
function normalizeSpecs(specs) {
  if (!Array.isArray(specs) || specs.length === 0) {
    throw new TypeError('at least one key spec is required');
  }
  return specs.map(normalizeSpec);
}

/**
 * Builds a comparator over rows from a list of key specs.
 * @param {unknown} specs Key specs, applied in order.
 * @returns {(a: unknown, b: unknown) => number} Comparator returning negative, zero, or positive.
 */
export function comparator(specs) {
  const normalized = normalizeSpecs(specs);
  return (a, b) => {
    for (const spec of normalized) {
      const left = spec.read(a);
      const right = spec.read(b);
      const leftAbsent = isAbsent(left);
      const rightAbsent = isAbsent(right);
      if (leftAbsent || rightAbsent) {
        if (leftAbsent && rightAbsent) continue;
        const nullsFirst = spec.nulls === 'first';
        return (leftAbsent ? -1 : 1) * (nullsFirst ? 1 : -1);
      }
      const order = compareValues(left, right);
      if (order !== 0) return spec.direction === 'asc' ? order : -order;
    }
    return 0;
  };
}

/**
 * Returns the permutation of row indices that sorts the rows.
 * @param {unknown} rows Rows to order.
 * @param {unknown} specs Key specs, applied in order.
 * @returns {number[]} Indices of `rows` in sorted order, stable for ties.
 */
export function sortIndices(rows, specs) {
  if (!Array.isArray(rows)) throw new TypeError('rows must be an array');
  const compare = comparator(specs);
  const indices = rows.map((_, i) => i);
  indices.sort((i, j) => {
    const order = compare(rows[i], rows[j]);
    return order !== 0 ? order : i - j;
  });
  return indices;
}

/**
 * Sorts rows without mutating the input.
 * @param {unknown} rows Rows to order.
 * @param {unknown} specs Key specs, applied in order.
 * @returns {unknown[]} New array holding the rows in sorted order.
 */
export function sortBy(rows, specs) {
  const indices = sortIndices(rows, specs);
  return indices.map((i) => rows[i]);
}
"}

