{"file_path":"src/index.js","content":"/**
 * Fixed-width plain-text tables: display width, wrapping, padding and layout.
 */

/** Error raised for invalid table input. */
export class TableError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'TableError';
    this.code = code;
  }
}

const WIDE_RANGES = [
  [0x1100, 0x115f],
  [0x2e80, 0x303e],
  [0x3041, 0x33ff],
  [0x3400, 0x4dbf],
  [0x4e00, 0x9fff],
  [0xa000, 0xa4cf],
  [0xac00, 0xd7a3],
  [0xf900, 0xfaff],
  [0xfe10, 0xfe19],
  [0xfe30, 0xfe6f],
  [0xff00, 0xff60],
  [0xffe0, 0xffe6],
  [0x1f300, 0x1f64f],
  [0x1f900, 0x1f9ff],
  [0x20000, 0x2fffd],
  [0x30000, 0x3fffd],
];

const ZERO_WIDTH_SET = new Set([0x200b, 0x200c, 0x200d, 0xfeff]);

/**
 * Column width of a single code point.
 *
 * @param {number} cp Unicode code point.
 * @returns {0|1|2} Column count for that code point.
 */
function codePointWidth(cp) {
  if (cp < 0x20 || cp === 0x7f) return 0;
  if (ZERO_WIDTH_SET.has(cp)) return 0;
  if (cp >= 0x300 && cp <= 0x36f) return 0;
  for (const [lo, hi] of WIDE_RANGES) {
    if (cp >= lo && cp <= hi) return 2;
  }
  return 1;
}

/**
 * Display width of a string in terminal columns.
 *
 * @param {string} text Text to measure.
 * @returns {number} Column count.
 */
export function stringWidth(text) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  let width = 0;
  for (const ch of text) {
    width += codePointWidth(ch.codePointAt(0));
  }
  return width;
}

/**
 * Validate that width is a positive integer, throwing otherwise.
 *
 * @param {number} width Candidate width.
 * @returns {void}
 */
function checkWidth(width) {
  if (!Number.isInteger(width) || width < 1) {
    throw new TableError('BAD_WIDTH', 'width must be a positive integer');
  }
}

/**
 * Break a single overlong word into width-fitting chunks.
 *
 * @param {string} word Word with no internal spaces.
 * @param {number} width Column width.
 * @returns {string[]} Chunks, each fitting within width.
 */
function breakWord(word, width) {
  const chunks = [];
  let current = '';
  let currentWidth = 0;
  for (const ch of word) {
    const w = codePointWidth(ch.codePointAt(0));
